-- Migration V9: Import existing user accounts and role mappings from local Oracle DB
-- Preserving user IDs to match MongoDB application and document records.

DELETE FROM REFRESH_TOKENS;
DELETE FROM USER_ROLES;
DELETE FROM USERS;

MERGE INTO USERS t USING (SELECT 'user@example.com' AS EMAIL, 'Test' AS FIRST_NAME, 'User' AS LAST_NAME, '$2a$10$msEGwApRNpIT4b8GgVxNQe5MAbYkro.pIlNNkaP2Lzx6KdUQc07Te' AS PASSWORD_HASH, '9876543210' AS PHONE_NUMBER, 'ACTIVE' AS ACCOUNT_STATUS, 1 AS EMAIL_VERIFIED, 3 AS ID FROM DUAL) s ON (t.EMAIL = s.EMAIL) WHEN NOT MATCHED THEN INSERT (ID, FIRST_NAME, LAST_NAME, EMAIL, PASSWORD_HASH, PHONE_NUMBER, ACCOUNT_STATUS, EMAIL_VERIFIED) VALUES (s.ID, s.FIRST_NAME, s.LAST_NAME, s.EMAIL, s.PASSWORD_HASH, s.PHONE_NUMBER, s.ACCOUNT_STATUS, s.EMAIL_VERIFIED);

