MERGE INTO USERS t USING (SELECT 'citizen@schemebridge.gov.in' AS EMAIL, 'Aarav' AS FIRST_NAME, 'Sharma' AS LAST_NAME, '$2a$10$VtDiHLfzjuitlhYD5GsrHuAzacFx7lzA//PY2ktX1rJBl0hOGtx06' AS PASSWORD_HASH, '9876543201' AS PHONE_NUMBER, 'ACTIVE' AS ACCOUNT_STATUS, 1 AS EMAIL_VERIFIED, 2 AS ID FROM DUAL) s ON (t.EMAIL = s.EMAIL) WHEN NOT MATCHED THEN INSERT (ID, FIRST_NAME, LAST_NAME, EMAIL, PASSWORD_HASH, PHONE_NUMBER, ACCOUNT_STATUS, EMAIL_VERIFIED) VALUES (s.ID, s.FIRST_NAME, s.LAST_NAME, s.EMAIL, s.PASSWORD_HASH, s.PHONE_NUMBER, s.ACCOUNT_STATUS, s.EMAIL_VERIFIED);

MERGE INTO USER_ROLES t USING (SELECT 2 AS USER_ID, r.ID AS ROLE_ID FROM ROLES r WHERE r.NAME = 'USER') s ON (t.USER_ID = s.USER_ID AND t.ROLE_ID = s.ROLE_ID) WHEN NOT MATCHED THEN INSERT (USER_ID, ROLE_ID) VALUES (s.USER_ID, s.ROLE_ID);

